    return self.energy.flatten()

def get_dominant_vector(self) -> Tuple[float, float, float]:
    """获取主导电场方向（能量加权平均）"""
    if not self._field_ready:
        self.compute_field()
    total_e = np.sum(self.energy) + 1e-12
    wx = np.sum(self.ex * self.energy) / total_e
    wy = np.sum(self.ey * self.energy) / total_e
    wz = np.sum(self.ez * self.energy) / total_e
    return (float(wx), float(wy), float(wz))

def _extract_tags(prompt: str, experts_used: List[str]) -> List[str]:
    """从 prompt 和命中专家中提取标签。"""
    tags = list(experts_used)
    # 简单关键词提取
    for kw in ["合鸣", "harmonia", "记忆", "memory", "子代理", "agent",
               "MoE", "电场", "field", "音乐", "music", "采样", "sampler"]:
        if kw.lower() in prompt.lower():
            tags.append(kw)
    return list(dict.fromkeys(tags))  # 去重保序

def _extract_keywords(prompt: str) -> List[str]:
    """从 prompt 提取检索关键词（与 HarmoniaLiteEngine._tokenize 对齐）。"""
    import re
    kws: List[str] = []
    for raw in re.findall(r"[A-Za-z0-9]+", prompt):
        if len(raw) >= 2:
            kws.append(raw.lower())
    for seg in re.findall(r"[\u4e00-\u9fff]+", prompt):
        chars = list(seg)
        for i in range(len(chars) - 1):
            kws.append(chars[i] + chars[i + 1])
    return kws

