def _join_two(a: str, b: str) -> str:
    """两个片段之间补恰当连接符。"""
    if not a:
        return b
    if not b:
        return a
    last = a[-1]
    first = b[0]
    if last in "。.；;！!？?，,":
        return a + b
    if first in "。.；;！!？?，,":
        return a + b
    return a + "，" + b

def _truncate(text: str, max_len: int) -> str:
    if len(text) <= max_len:
        return text
    cut = text[:max_len]
    # 优先在句末断句
    for sep in "。.！!？?；;":
        idx = cut.rfind(sep)
        if idx >= max_len // 2:
            return cut[: idx + 1]
    # 退而求其次：在逗号处断句（不在词中间硬切）
    for sep in "，,":
        idx = cut.rfind(sep)
        if idx >= max_len // 2:
            return cut[: idx + 1]
    return cut

def _bigram_graph(frags: List[str]) -> Dict[str, Dict[str, int]]:
    graph: Dict[str, Dict[str, int]] = {}
    for f in frags:
        chars = list(f)
        for i in range(len(chars) - 1):
            a, b = chars[i], chars[i + 1]
            graph.setdefault(a, {})
            graph[a][b] = graph[a].get(b, 0) + 1
    return graph

def _extract_fragments(data) -> List[str]:
    if data is None:
        return []
    if isinstance(data, str):
        # 按句切分
        import re
        return [s.strip() for s in re.split(r"[。.！!？?\n]+", data) if s.strip()]
    if isinstance(data, (list, tuple)):
        return [str(s).strip() for s in data if str(s).strip()]
    return []

